import { readFile, writeFile } from 'node:fs/promises';

// This common Zod subset runs under frontend Zod 4 and backend Zod 3.
// Keep the frontend schema authoritative; never edit the backend copy by hand.
const source = new URL('../src/features/exams/authoring/generation-schemas.ts', import.meta.url);
const destination = new URL(
  '../nexora-backend/src/modules/authoring/generation-schemas.ts',
  import.meta.url,
);
await writeFile(
  destination,
  '// Generated by node scripts/sync-generation-contract.ts. Do not edit.\n' +
    (await readFile(source, 'utf8')),
);
